um != -1 && entries[untilEntryNum].type == xrefEntryNone))", "note": "Entry 99 still missing, calls constructXRef"}, {"step": 10, "file": "poppler/XRef.cc", "function": "XRef::constructXRef", "line": 830, "var": "entries", "code": "resize(0); gfree(entries); entries = nullptr;", "note": "Frees the old entries array, entry pointer in makeStream is now dangling"}, {"step": 11, "file": "poppler/Parser.cc", "function": "Parser::makeStream", "line": 294, "var": "entry", "code": "entry->setFlag(XRefEntry::Parsing, false)", "note": "Use-after-free: writes to freed XRefEntry memory via dangling pointer"}
